import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
/** Independent inverse audit of the explicit cancellation status port. */
public final class CompanionForestCancellationDelta {
 static final String P="local/lito381/server/",B=P+"BattleCompanion",H=P+"NativeCompanionForestCancellation";
 static ClassNode read(JarFile j,String n)throws Exception{var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry(n+".class"))).accept(c,ClassReader.SKIP_DEBUG|ClassReader.EXPAND_FRAMES);return c;}
 static byte[] method(ClassNode c,MethodNode m){var q=new ClassNode();q.version=c.version;q.access=c.access;q.name=c.name;q.superName=c.superName;q.methods.add(m);var w=new ClassWriter(0);q.accept(w);return w.toByteArray();}
 public static void main(String[]a)throws Exception{try(var old=new JarFile(a[0]);var next=new JarFile(a[1])){
  var names=new HashSet<String>();var changed=new HashSet<String>();for(var e:Collections.list(old.entries())){names.add(e.getName());var n=next.getJarEntry(e.getName());if(n==null)throw new AssertionError("removed entry");if(!Arrays.equals(old.getInputStream(e).readAllBytes(),next.getInputStream(n).readAllBytes()))changed.add(e.getName());}var fresh=new HashSet<String>();for(var e:Collections.list(next.entries()))if(!names.contains(e.getName()))fresh.add(e.getName());if(!changed.equals(Set.of(B+".class"))||!fresh.equals(Set.of(H+".class")))throw new AssertionError("archive isolation");
  var b=read(old,B);var n=read(next,B);if(b.fields.size()!=n.fields.size()||b.methods.size()!=n.methods.size())throw new AssertionError("schema changed");for(int i=0;i<b.fields.size();i++){var x=b.fields.get(i);var y=n.fields.get(i);if(!x.name.equals(y.name)||!x.desc.equals(y.desc)||x.access!=y.access||!Objects.equals(x.value,y.value))throw new AssertionError("field changed");}
  int count=0;for(var m:b.methods){var q=n.methods.stream().filter(v->v.name.equals(m.name)&&v.desc.equals(m.desc)).findFirst().orElseThrow();for(var ins:q.instructions)if(ins instanceof MethodInsnNode v&&v.owner.equals(H)){if(!m.name.equals("cancelMagicEffects")||!v.name.equals("cancel"))throw new AssertionError("unexpected port");v.owner=P+"CombatNpcDebuffs";count++;}if(!Arrays.equals(method(b,m),method(n,q)))throw new AssertionError("original body changed "+m.name);}if(count!=1)throw new AssertionError("port count");
  var h=read(next,H);if(!h.fields.isEmpty())throw new AssertionError("owned state");for(var m:h.methods)for(var ins:m.instructions){if(ins instanceof TypeInsnNode v&&v.getOpcode()==Opcodes.NEW)throw new AssertionError("new allocation");if(ins instanceof MethodInsnNode v&&(v.owner.startsWith("java/sql/")||v.owner.startsWith("java/nio/file/")||v.owner.contains("AccountRepository")||v.owner.contains("GameStateStore")||v.owner.contains("Thread")||v.owner.contains("Executor")))throw new AssertionError("IO/lifetime dependency");}
 }System.out.println("PASS one class/one stateless helper; exact inverse single explicit cancellation port, original methods/fields/archive intact; no allocation/worker/registry/TLS/SQL/file owner");}
}
